"""PreToolUse hook: refuse edits to generated files and say what to change instead (exit 2 = block, stderr goes to Claude)."""
import json
import os
import sys
from pathlib import Path

RULES = [  # (path prefix relative to the project, what to do instead)
    ("out/", "out/ is generated by `python -m biwiki build`; change the code in biwiki/ and rebuild."),
    ("data/schema.json", "data/schema.json is copied from biwiki/schema.json by the build; edit that one."),
    ("data/raw/", "data/raw/ is the wikitext cache written by `python -m biwiki sync`; never edit it by hand."),
    ("data/", "data/ holds generated JSON (a clone of a3ref/data); change the parser in biwiki/ and run "
              "`python -m biwiki --dataset data build`. Only its README.md, AGENTS.md, CLAUDE.md and .github/ are hand-written."),
    ("mcp/dist/", "mcp/dist/ is the bundle built from mcp/src/; edit mcp/src/ and run `npm run build` in mcp/."),
    ("tests/fixtures/raw/", "Fixtures are copies of real wiki pages; regenerate them with `python tests/fixtures/refresh.py`."),
]
HAND_WRITTEN = ("data/README.md", "data/.gitattributes", "data/AGENTS.md", "data/CLAUDE.md", "data/.github/", "data/.claude/")

event = json.load(sys.stdin)
path = event.get("tool_input", {}).get("file_path")
if not path:
    sys.exit(0)
root = Path(os.environ.get("CLAUDE_PROJECT_DIR") or event.get("cwd") or ".").resolve()
try:
    rel = Path(path).resolve().relative_to(root).as_posix()
except ValueError:
    sys.exit(0)
if rel.startswith(HAND_WRITTEN):
    sys.exit(0)
for prefix, advice in RULES:
    if rel == prefix or rel.startswith(prefix):
        print(f"Blocked: {rel}. {advice}", file=sys.stderr)
        sys.exit(2)
